A minimal component
One chart of monthly revenue per customer from an orders table, filtered by sales channel.
app/Livewire/RevenueByMonth.php:
namespace App\Livewire;

use App\Models\Order;
use Livewire\Component;
use Phibble\DataFrame;
use Phiz\Plot;

use function Phplyr\{
    col, floor_date, group_by, mutate, sum, summarize,
};

class RevenueByMonth extends Component
{
    public string $channel = 'All';

    public function render()
    {
        $orders = Order::query()-&gt;when(
            $this-&gt;channel !== 'All',
            fn ($q) =&gt; $q-&gt;where('channel', $this-&gt;channel),
        );

        $monthly = DataFrame::fromQuery($orders) |&gt;
            mutate(
                month: floor_date(col('placed_on'), 'month'),
            ) |&gt;
            group_by('month', 'customer') |&gt;
            summarize(revenue: sum('total'));

        $chart = Plot::of($monthly)
            -&gt;aes(x: 'month', y: 'revenue', color: 'customer')
            -&gt;line()
            -&gt;point()
            -&gt;labs(x: null, y: 'Revenue ($)', color: null)
            -&gt;size('container', 260);

        return view('livewire.revenue-by-month', [
            'chart' =&gt; $chart,
        ]);
    }
}
resources/views/livewire/revenue-by-month.blade.php:
&lt;div&gt;
    &lt;select wire:model.live="channel"&gt;
        &lt;option&gt;All&lt;/option&gt;
        &lt;option&gt;Web&lt;/option&gt;
        &lt;option&gt;App&lt;/option&gt;
        &lt;option&gt;Marketplace&lt;/option&gt;
    &lt;/select&gt;

    &lt;x-phiz :plot="$chart" /&gt;
&lt;/div&gt;

Redrawing. Livewire reruns render() after each property change. &lt;x-phiz&gt; redraws the chart when its specification changes.
Server-side data. The query, the monthly summary, and the chart are built in PHP. The page receives only the summarized rows.
Width. size('container', 260) makes the chart fill its element’s width at a fixed height.

A linked dashboard
Three charts follow the same filters: a drive and a year selected in the page, and a vehicle class selected from a list. A shared function builds the charts, a component holds the state, and a view lays them out.

The shared function
fuel_dashboard() takes the cars table and the filter state. It returns three plots and the class summary behind the bar chart. The file is examples/dashboard.php, and examples/dashboard.chain.php is the method-chain version.

PHP 8.5+PHP 8.3–8.4


use Phibble\Contracts\Table;
use Phiz\Plot;

use function Phiz\{aes, calc, field};
use function Phplyr\{
    arrange, desc, filter, group_by, mean, n, summarize,
};

/**
 * @param string|null $drive 'f', 'r', '4', or null for all
 * @param int|null $year 1999, 2008, or null for both
 * @return array{summary: Table, bars: Plot,
 *     scatter: Plot, trend: Plot}
 */
function fuel_dashboard(
    Table $cars,
    ?string $drive = null,
    ?int $year = null,
    ?string $selected = null,
): array {
    $byDrive = $cars |&gt; filter(
        fn ($r) =&gt; $drive === null || $r-&gt;drv === $drive,
    );
    $subset = $byDrive |&gt; filter(
        fn ($r) =&gt; $year === null || $r-&gt;year === $year,
    );

    $byClass = $subset |&gt;
        group_by('class') |&gt;
        summarize(
            cars: n(),
            hwy: mean('hwy'),
            cty: mean('cty'),
        ) |&gt;
        arrange(desc('hwy'));

    // The trend compares the years, so it ignores $year.
    $byManufacturer = $byDrive |&gt;
        group_by('manufacturer', 'year') |&gt;
        summarize(hwy: mean('hwy'));

    $test = 'datum.class === '.json_encode($selected ?? '');

    $bars = Plot::of($byClass)
        -&gt;aes(
            x: 'hwy',
            y: field('class', sort: '-x'),
            fill: calc($test, 'selected', 'nominal'),
        )
        -&gt;col()
        -&gt;scaleFill(
            domain: [false, true],
            range: ['#9ECAE1', '#08519C'],
            guide: false,
        )
        -&gt;tooltip(['class', 'cars', 'hwy', 'cty'])
        -&gt;labs(
            title: 'Mean highway mpg by class',
            x: 'Highway mpg',
            y: null,
        )
        -&gt;size('container', 220);

    $scatter = Plot::of($subset)
        -&gt;aes(x: 'displ', y: 'hwy', color: 'class')
        -&gt;point(alpha: 0.7, size: 40)
        -&gt;smooth(
            aes(x: 'displ', y: 'hwy'),
            method: 'lm',
            color: '#333333',
            inheritAes: false,
        )
        -&gt;tooltip([
            'manufacturer', 'model', 'year', 'displ', 'hwy',
        ])
        -&gt;theme(legendPosition: 'bottom')
        -&gt;labs(
            title: 'Displacement and highway mpg',
            x: 'Displacement (L)',
            y: 'Highway mpg',
            color: null,
        )
        -&gt;size('container', 220);

    $trend = Plot::of($byManufacturer)
        -&gt;aes(x: 'year:O', y: 'hwy', group: 'manufacturer')
        -&gt;line(color: '#BBBBBB')
        -&gt;point(color: '#666666', size: 20)
        -&gt;tooltip(['manufacturer', 'year', 'hwy'])
        -&gt;labs(
            title: 'Manufacturers, 1999 to 2008',
            x: null,
            y: 'Mean highway mpg',
        )
        -&gt;size('container', 220);

    return [
        'summary' =&gt; $byClass,
        'bars' =&gt; $bars,
        'scatter' =&gt; $scatter,
        'trend' =&gt; $trend,
    ];
}


use Phibble\Contracts\Table;
use Phiz\Plot;

use function Phiz\{aes, calc, field};
use function Phplyr\{desc, mean, n, phplyr};

/**
 * @param string|null $drive 'f', 'r', '4', or null for all
 * @param int|null $year 1999, 2008, or null for both
 * @return array{summary: Table, bars: Plot,
 *     scatter: Plot, trend: Plot}
 */
function fuel_dashboard(
    Table $cars,
    ?string $drive = null,
    ?int $year = null,
    ?string $selected = null,
): array {
    $byDrive = phplyr($cars)
        -&gt;filter(
            fn ($r) =&gt; $drive === null || $r-&gt;drv === $drive,
        )
        -&gt;get();
    $subset = phplyr($byDrive)
        -&gt;filter(
            fn ($r) =&gt; $year === null || $r-&gt;year === $year,
        )
        -&gt;get();

    $byClass = phplyr($subset)
        -&gt;groupBy('class')
        -&gt;summarize(
            cars: n(),
            hwy: mean('hwy'),
            cty: mean('cty'),
        )
        -&gt;arrange(desc('hwy'))
        -&gt;get();

    // The trend compares the years, so it ignores $year.
    $byManufacturer = phplyr($byDrive)
        -&gt;groupBy('manufacturer', 'year')
        -&gt;summarize(hwy: mean('hwy'))
        -&gt;get();

    $test = 'datum.class === '.json_encode($selected ?? '');

    $bars = Plot::of($byClass)
        -&gt;aes(
            x: 'hwy',
            y: field('class', sort: '-x'),
            fill: calc($test, 'selected', 'nominal'),
        )
        -&gt;col()
        -&gt;scaleFill(
            domain: [false, true],
            range: ['#9ECAE1', '#08519C'],
            guide: false,
        )
        -&gt;tooltip(['class', 'cars', 'hwy', 'cty'])
        -&gt;labs(
            title: 'Mean highway mpg by class',
            x: 'Highway mpg',
            y: null,
        )
        -&gt;size('container', 220);

    $scatter = Plot::of($subset)
        -&gt;aes(x: 'displ', y: 'hwy', color: 'class')
        -&gt;point(alpha: 0.7, size: 40)
        -&gt;smooth(
            aes(x: 'displ', y: 'hwy'),
            method: 'lm',
            color: '#333333',
            inheritAes: false,
        )
        -&gt;tooltip([
            'manufacturer', 'model', 'year', 'displ', 'hwy',
        ])
        -&gt;theme(legendPosition: 'bottom')
        -&gt;labs(
            title: 'Displacement and highway mpg',
            x: 'Displacement (L)',
            y: 'Highway mpg',
            color: null,
        )
        -&gt;size('container', 220);

    $trend = Plot::of($byManufacturer)
        -&gt;aes(x: 'year:O', y: 'hwy', group: 'manufacturer')
        -&gt;line(color: '#BBBBBB')
        -&gt;point(color: '#666666', size: 20)
        -&gt;tooltip(['manufacturer', 'year', 'hwy'])
        -&gt;labs(
            title: 'Manufacturers, 1999 to 2008',
            x: null,
            y: 'Mean highway mpg',
        )
        -&gt;size('container', 220);

    return [
        'summary' =&gt; $byClass,
        'bars' =&gt; $bars,
        'scatter' =&gt; $scatter,
        'trend' =&gt; $trend,
    ];
}




Selection. A computed selected field colors the selected class in the bar chart.
One fit. The scatterplot’s linear fit sets inheritAes: false, so it fits all filtered cars together instead of one line per class.
Trend. The trend chart ignores the year filter, so both years stay visible.

